  // MAX_DEPTH, into the same runtime error, reported at the innermost call
  // site that has enough stack left to build the error.
  function unwind(e, site) {
    if (e instanceof RuneScriptError || e instanceof RSError) return e;
    if (e instanceof RangeError || (e && e.name === "InternalError")) {
      fatal = true;
      return new RuneScriptError(CODES.callDepth, ...at(site),
        `maximum call depth exceeded: the JavaScript host ran out of stack at depth ${depth} (limit ${MAX_DEPTH})`);
    }
    return e;
  }

  // caught is what a catch clause sees: a RuneScript error. Anything else
  // (an error that cannot be caught) is thrown on.
  function caught(e, site) {
    if (e instanceof RSError && !fatal) return e;
    throw unwind(e, site);
  }

  function trace(...args) {
    sink(args.map(String).join(" "));
  }

  // Fault is a deliberate failure of a standard library function: it
  // becomes a RuneScript error of the given type (stdlib.Fault in Go).
  class Fault {
    constructor(type, message) { this.type = type; this.message = message; }
  }

  // std holds the standard library packages a program uses; each one's
  // section adds itself.
  const std = {};

  // native calls a standard library function. Its failures become runtime
  // errors, and integer results are range-checked like the interpreter's.
  function native(site, name, result, impl, ...args) {
    let r;
    try {
      r = impl(...args);
    } catch (e) {
      if (e instanceof RuneScriptError || e instanceof RSError) throw e;
      if (e instanceof Fault) fail(CODES.nativeFailed, site, `${name}: ${e.message}`, e.type);
      fail(CODES.nativeFailed, site, `${name} failed: ${e.message}`);
    }
    if ((result === "int" && !(r >= INT_MIN && r <= INT_MAX)) ||
        (result === "uint" && !(r >= 0 && r <= UINT_MAX))) {
      fail(CODES.overflow, site, `${name} returned ${r}, which does not fit in '${result}'`);
    }
    return r;
  }

  //@section extern
  // ---- extern (JavaScript) functions (OQ-JS-02) ----
  //
  // Arguments need no checks: RuneScript values are already valid
  // JavaScript values, and errors are RSError objects. Everything coming
  // back is checked against its declared type, because JavaScript code is
  // not type-checked: a wrong value throws a RuneScript TypeError
  // (externResult), and a JavaScript exception becomes a RuneScript Error
  // (externThrew). An RSError thrown or returned by JavaScript crosses as
  // it is, once checked.

  const ERROR_TYPES = { Error: true, RangeError: true, TypeError: true, ArgumentError: true };

  // wellFormed reports whether s has no lone surrogates, so that it is a
  // valid RuneScript (UTF-8) string; toWellFormed replaces them by U+FFFD.
  function wellFormed(s) {
    for (let i = 0; i < s.length; i++) {
      const c = s.charCodeAt(i);
      if (c >= 0xD800 && c <= 0xDBFF) {
        const d = s.charCodeAt(i + 1);
        if (!(d >= 0xDC00 && d <= 0xDFFF)) return false;
        i++;
      } else if (c >= 0xDC00 && c <= 0xDFFF) {
        return false;
      }
    }
    return true;
  }
  const toWellFormed = (s) =>
    wellFormed(s) ? s : Array.from(s, (c) => (c.length === 1 && c >= "\uD800" && c <= "\uDFFF" ? "�" : c)).join("");

  // describe names a JavaScript value in an error message.
  function describe(v) {
    if (typeof v === "string") return toWellFormed(JSON.stringify(v));
    if (typeof v === "bigint") return v + "n";
    if (typeof v === "function") return "a function";
    if (v instanceof RSError) return "an error value (" + toWellFormed(String(v.name)) + ")";
    if (v instanceof Error) return "a JavaScript " + toWellFormed(String(v.name));
    if (v !== null && typeof v === "object") return "an object";
    return String(v);
  }

  const validError = (e) =>
    e instanceof RSError && ERROR_TYPES[e.name] === true && typeof e.message === "string" && wellFormed(e.message) &&
    Number.isInteger(e.errorID) && e.errorID >= INT_MIN && e.errorID <= INT_MAX;

  // fromJS converts a JavaScript Error into a RuneScript error value.
  const fromJS = (e) =>
    newError(e.name === "RangeError" || e.name === "TypeError" ? e.name : "Error", toWellFormed(String(e.message)), 0);

  // ext calls the extern function name of module. kind is the result's
  // conversion code (i, u, f, f32, b, s), "v" for void, or an error type's
  // name; type is the result type as written.
  function ext(site, name, module, kind, type, fn, ...args) {
    if (typeof fn !== "function") {
      fail(CODES.externThrew, site, `${module} has no function '${name}'`);
    }
    let r;
    try {
      r = fn(...args);
    } catch (e) {
      if (e instanceof RuneScriptError) throw e;
      if (validError(e)) throw thrown(e, site);
      if (e instanceof RSError) {
        fail(CODES.externResult, site, `${name} threw an invalid error value`, "TypeError");
      }
      const what = e instanceof Error ? toWellFormed(String(e.name)) + ": " + toWellFormed(String(e.message)) : describe(e);
      fail(CODES.externThrew, site, `${name} threw ${what}`);
    }
    const bad = () => fail(CODES.externResult, site, `${name} returned ${describe(r)}, but its result type is '${type}'`, "TypeError");
    switch (kind) {
      case "i":
        return typeof r === "number" && Number.isInteger(r) && r >= INT_MIN && r <= INT_MAX ? r + 0 : bad();
      case "u":
        return typeof r === "number" && Number.isInteger(r) && r >= 0 && r <= UINT_MAX ? r + 0 : bad();
      case "f":
        return typeof r === "number" ? r : bad();
      case "f32":
        return typeof r === "number" ? Math.fround(r) : bad(); // rounded (owner decision)
      case "b":
        return typeof r === "boolean" ? r : bad();
      case "s":
        return typeof r === "string" && wellFormed(r) ? r : bad();
      case "v":
        return r === undefined ? r : bad();
    }
    if (validError(r) && isA(r, kind)) return r;
    if (r instanceof Error && !(r instanceof RSError)) {
      const e = fromJS(r);
      if (isA(e, kind)) return e;
    }
    return bad();
  }

  //@end

  //@section dom
  // ---- runes and the DOM (rune:dom, OQ-DOM-01) ----
  //
  // A rune is a signal, as in SolidJS. A binding is a computation that
  // updates one part of the DOM: reading a rune while a binding runs
  // subscribes the binding to it, and setting the rune runs exactly the
  // bindings that read it. There is no virtual DOM and no re-rendering.
  //
  // Bindings form an ownership tree: a binding created while another runs
  // belongs to it, and is disposed when its owner runs again or is
  // disposed, so an $if branch that is removed takes its bindings along.

  let owner = null; // the binding or scope being built or run

  function scope(parent) {
    const s = { deps: new Set(), kids: [], dead: false };
    if (parent) parent.kids.push(s);
    return s;
  }
  function dispose(s) {
    for (const subs of s.deps) subs.delete(s);
    s.deps.clear();
    for (const k of s.kids) {
      k.dead = true;
      dispose(k);
    }
    s.kids = [];
  }
  function within(s, fn) {
    const prev = owner;
    owner = s;
    try {
      return fn();
    } finally {
      owner = prev;
    }
  }
  // bind runs fn now and again whenever a rune it read changes.
  function bind(fn) {
    const b = scope(owner);
    b.run = () => {
      if (b.dead) return;
      dispose(b);
      within(b, fn);
    };
    b.run();
  }

  function signal(value) {
    const subs = new Set();
    return {
      get() {
        if (owner && owner.run) {
          subs.add(owner);
          owner.deps.add(subs);
        }
        return value;
      },
      set(v) {
        if (Object.is(v, value)) return;
        value = v;
        for (const b of Array.from(subs)) b.run();
      },
    };
  }

  const SVG_NS = "http://www.w3.org/2000/svg";
  const el = (svg, tag) => (svg ? document.createElementNS(SVG_NS, tag) : document.createElement(tag));
  const text = (parent, s) => parent.appendChild(document.createTextNode(s));

  // display turns a value from {{ }} into text, as trace does.
  const display = (v, kind) => (kind === "f32" ? f32str(v) : String(v));

  // bindText keeps a text node equal to {{ fn() }}.
  function bindText(parent, fn, kind) {
    const t = text(parent, "");
    bind(() => {
      t.data = display(fn(), kind);
    });
  }

  // bindNode keeps the element {{ fn() }} (a child component) in place.
  function bindNode(parent, fn) {
    const anchor = parent.appendChild(document.createComment(""));
    let node = null;
    bind(() => {
      const n = fn();
      if (node) node.remove();
      node = n;
      anchor.parentNode.insertBefore(n, anchor);
    });
  }

  // safeURL rejects URLs that would run script, so that a {{ }} value
  // can never inject code into a link, as text can never inject markup.
  function safeURL(v, site, name) {
    if (/^[\u0000- ]*(javascript|vbscript|data):/i.test(v.replace(/[\t\n\r]/g, ""))) {
      fail(CODES.domValue, site, `${name}: refusing the URL ${JSON.stringify(v)}, which would run script`, "TypeError");
    }
    return v;
  }

  // attr sets a static attribute; bool attributes are present or absent.
  const attr = (e, name, v) => (v === true ? e.setAttribute(name, "") : e.setAttribute(name, v));

  // bindAttr keeps the attribute name equal to {{ fn() }}. kind is "bool",
  // "url", "f32", or "" (any other value is shown as text); values, if
  // not null, are the keywords the attribute allows.
  function bindAttr(e, name, fn, kind, values, site) {
    bind(() => {
      const v = fn();
      if (kind === "bool") {
        if (v) e.setAttribute(name, "");
        else e.removeAttribute(name);
        return;
      }
      let s = display(v, kind);
      if (values !== null && values.indexOf(s) < 0) {
        fail(CODES.domValue, site, `${name}: ${JSON.stringify(s)} is not one of ${values.map((x) => JSON.stringify(x)).join(", ")}`, "TypeError");
      }
      if (kind === "url") s = safeURL(s, site, name);
      e.setAttribute(name, s);
    });
  }

  // on calls the RuneScript function handler for the event. An error that
  // nothing caught is reported like run's: as a RuneScriptError.
  function on(e, event, handler, site) {
    e.addEventListener(event, () => {
      try {
        handler(site);
      } catch (x) {
        throw x instanceof RSError ? report(x) : x;
      }
    });
  }

  // when is $if: test() returns the index of the branch to show (-1 for
  // none), and build(i) builds branch i's nodes. A branch is rebuilt only
  // when the index changes.
  function when(parent, test, build) {
    const anchor = parent.appendChild(document.createComment(""));
    const holder = owner;
    let shown = -2, nodes = [], branch = null;
    bind(() => {
      const i = test();
      if (i === shown) return;
      shown = i;
      if (branch) dispose(branch);
      for (const n of nodes) n.remove();
      branch = scope(holder);
      const frag = document.createDocumentFragment();
      if (i >= 0) within(branch, () => build(i, frag));
      nodes = Array.from(frag.childNodes);
      anchor.parentNode.insertBefore(frag, anchor);
    });
  }

  // each is $foreach: items() returns the array, and build(x, frag) builds
  // the nodes for element x. The list is rebuilt when a rune that items()
  // read changes. As in for each, the length is read before every element.
  function each(parent, items, build) {
    const anchor = parent.appendChild(document.createComment(""));
    const holder = owner;
    let nodes = [], list = null;
    bind(() => {
      const a = items();
      if (list) dispose(list);
      for (const n of nodes) n.remove();
      list = scope(holder);
      const frag = document.createDocumentFragment();
      within(list, () => {
        for (let i = 0; i < a.length; i++) build(a[i], frag);
      });
      nodes = Array.from(frag.childNodes);
      anchor.parentNode.insertBefore(frag, anchor);
    });
  }

  // renderApp calls the component and puts its element into the first
  // element selector matches, replacing what was there.
  function renderApp(component, selector, site) {
    const target = typeof document === "undefined" ? null : document.querySelector(selector);
    if (target === null) {
      fail(CODES.noMountTarget, site, `renderApp: no element matches ${JSON.stringify(selector)}`);
    }
    const root = scope(null);
    const node = within(root, () => component(site));
    while (target.firstChild) target.removeChild(target.firstChild);
    target.appendChild(node);
  }

  //@end

  //@section string
  // ---- std:string ----
  //
  // Positions and lengths are UTF-8 byte offsets, as in Go (owner decision,
  // v0.2). RuneScript strings are always valid UTF-8, so they map one to
  // one onto well-formed JavaScript strings; offsets are converted at the
  // boundary. Case mapping, case folding, and white space use tables taken
  // from Go's unicode package by the generator, so results match the
  // interpreter exactly.

  // utf8Len is the UTF-8 length of s[from:to] (UTF-16 indexes).
  function utf8Len(s, from = 0, to = s.length) {
    let n = 0;
    for (let i = from; i < to; i++) {
      const c = s.charCodeAt(i);
      if (c < 0x80) n += 1;
      else if (c < 0x800) n += 2;
      else if (c >= 0xD800 && c <= 0xDBFF) { n += 4; i++; }
      else n += 3;
    }
    return n;
  }
  const byteIndex = (s, i) => (i < 0 ? -1 : utf8Len(s, 0, i));
  const codePoints = (s) => Array.from(s, (c) => c.codePointAt(0));
  const width = (cp) => (cp > 0xFFFF ? 2 : 1);

  // Tables are flat runs [start, count, step, delta, ...]: for k < count,
  // code point start+k*step maps to itself plus delta.
  function table(runs) {
    const m = new Map();
    for (let i = 0; i < runs.length; i += 4) {
      const [start, count, step, delta] = runs.slice(i, i + 4);
      for (let k = 0; k < count; k++) m.set(start + k * step, start + k * step + delta);
    }
    return m;
  }
  const lazy = (runs) => { let m = null; return () => m ?? (m = table(runs)); };
  const upper = lazy(/*@UPPER@*/), lower = lazy(/*@LOWER@*/), title = lazy(/*@TITLE@*/);
  const fold = lazy(/*@FOLD@*/);
  const SPACE = new Set(/*@SPACE@*/);

  const mapCase = (s, tab) => {
    const m = tab();
    let out = "";
    for (const c of s) {
      const cp = c.codePointAt(0);
      out += m.has(cp) ? String.fromCodePoint(m.get(cp)) : c;
    }
    return out;
  };

  function indexAny(s, chars, last) {
    if (chars === "") return -1;
    const set = new Set(codePoints(chars));
    let found = -1;
    for (let i = 0; i < s.length;) {
      const cp = s.codePointAt(i);
      if (set.has(cp)) {
        found = i;
        if (!last) break;
      }
      i += width(cp);
    }
    return byteIndex(s, found);
  }

  // The trim helpers take a predicate on code points: a set's has, or a
  // RuneScript callback. They call it in the same order as Go does.
  function trimLeft(s, has) {
    let i = 0;
    while (i < s.length && has(s.codePointAt(i))) i += width(s.codePointAt(i));
    return s.slice(i);
  }
  // before is the code point ending at UTF-16 index j.
  const before = (s, j) => s.codePointAt(j >= 2 && s.charCodeAt(j - 1) >= 0xDC00 && s.charCodeAt(j - 1) <= 0xDFFF ? j - 2 : j - 1);
  function trimRight(s, has) {
    let j = s.length;
    while (j > 0) {
      const cp = before(s, j);
      if (!has(cp)) break;
      j -= width(cp);
    }
    return s.slice(0, j);
  }
  const cutset = (chars) => { const set = new Set(codePoints(chars)); return (cp) => set.has(cp); };
  const spaces = (cp) => SPACE.has(cp);

  // indexFunc is the byte offset of the first (or, if last, the last)
  // character f accepts, or -1.
  function indexFunc(s, f, last) {
    if (last) {
      for (let j = s.length; j > 0;) {
        const cp = before(s, j);
        j -= width(cp);
        if (f(cp)) return byteIndex(s, j);
      }
      return -1;
    }
    for (let i = 0; i < s.length;) {
      const cp = s.codePointAt(i);
      if (f(cp)) return byteIndex(s, i);
      i += width(cp);
    }
    return -1;
  }

  // compareUnits orders UTF-16 code units by code point, which is UTF-8
  // byte order: surrogates (D800-DFFF) sort after E000-FFFF.
  const fixup = (c) => (c >= 0xD800 ? (c >= 0xE000 ? c - 0x800 : c + 0x2000) : c);

  function count(s, sub) {
    if (sub === "") return codePoints(s).length + 1;
    return s.split(sub).length - 1;
  }

  // genSplit follows Go's strings.genSplit: at most n pieces (all if
  // n < 0), each keeping the separator if save is set. An empty separator
  // splits into characters (Go's explode).
  function genSplit(s, sep, save, n) {
    if (n === 0) return [];
    if (sep === "") {
      const cs = Array.from(s);
      if (n < 0 || n > cs.length) n = cs.length;
      const out = cs.slice(0, Math.max(n - 1, 0));
      if (n > 0) out.push(cs.slice(n - 1).join(""));
      return out;
    }
    if (n < 0) n = count(s, sep) + 1;
    const out = [];
    while (out.length < n - 1) {
      const m = s.indexOf(sep);
      if (m < 0) break;
      out.push(s.slice(0, save ? m + sep.length : m));
      s = s.slice(m + sep.length);
    }
    out.push(s);
    return out;
  }

  // fieldsFunc follows Go's strings.FieldsFunc: the runs of characters f
  // rejects, calling f once per character, in order.
  function fieldsFunc(s, f) {
    const out = [];
    let start = -1;
    for (let i = 0; i < s.length;) {
      const cp = s.codePointAt(i);
      if (f(cp)) {
        if (start >= 0) out.push(s.slice(start, i));
        start = -1;
      } else if (start < 0) {
        start = i;
      }
      i += width(cp);
    }
    if (start >= 0) out.push(s.slice(start));
    return out;
  }

  // replace follows Go's strings.Replace, in UTF-16 indexes.
  function replace(s, old, nw, n) {
    if (old === nw || n === 0) return s;
    const m = count(s, old);
    if (m === 0) return s;
    if (n < 0 || m < n) n = m;
    let out = "", start = 0;
    for (let i = 0; i < n; i++) {
      let j = start;
      if (old === "") {
        if (i > 0) j += width(s.codePointAt(start));
      } else {
        j = s.indexOf(old, start);
      }
      out += s.slice(start, j) + nw;
      start = j + old.length;
    }
    return out + s.slice(start);
  }

  // unitIndex converts byte offset b of s to a UTF-16 index, or -1 if b
  // is inside a character.
  function unitIndex(s, b) {
    let n = 0, i = 0;
    while (n < b && i < s.length) {
      const cp = s.codePointAt(i);
      n += cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
      i += width(cp);
    }
    return n === b ? i : -1;
  }

  // slice is s[start:end] in UTF-8 bytes; it never cuts a character.
  function slice(s, start, end) {
    const len = utf8Len(s);
    if (start < 0 || end > len || start > end) {
      throw new Fault("RangeError", `bounds [${start}:${end}] are out of range for a string of ${len} bytes`);
    }
    const i = unitIndex(s, start), j = unitIndex(s, end);
    if (i < 0) throw new Fault("RangeError", `byte offset ${start} is inside a character`);
    if (j < 0) throw new Fault("RangeError", `byte offset ${end} is inside a character`);
    return s.slice(i, j);
  }

  // utf8 encodes and decodes for string.bytes and string.fromBytes; the
  // decoder matches std:fs's readFile (WHATWG UTF-8, the BOM kept).
  let utf8Encoder = null, utf8Decoder = null;
  const string = {
    bytes(s) {
      if (utf8Encoder === null) utf8Encoder = new TextEncoder();
      return Array.from(utf8Encoder.encode(s));
    },
    fromBytes(b) {
      if (utf8Decoder === null) utf8Decoder = new TextDecoder("utf-8", { ignoreBOM: true });
      return utf8Decoder.decode(Uint8Array.from(b));
    },
    clone: (s) => s,
    compare(a, b) {
      const n = Math.min(a.length, b.length);
      for (let i = 0; i < n; i++) {
        const x = a.charCodeAt(i), y = b.charCodeAt(i);
        if (x !== y) return fixup(x) < fixup(y) ? -1 : 1;
      }
      return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
    },
    contains: (s, sub) => s.includes(sub),
    containsAny: (s, chars) => indexAny(s, chars, false) >= 0,
    containsFunc: (s, f) => indexFunc(s, f, false) >= 0,
    containsRune: (s, c) => s.includes(String.fromCodePoint(c)),
    count,
    equalFold(s, t) {
      const a = codePoints(s), b = codePoints(t), f = fold();
      if (a.length !== b.length) return false;
      const canon = (cp) => (f.has(cp) ? f.get(cp) : cp);
      return a.every((cp, i) => cp === b[i] || canon(cp) === canon(b[i]));
    },
    fields: (s) => fieldsFunc(s, spaces),
    fieldsFunc,
    hasPrefix: (s, p) => s.startsWith(p),
    hasSuffix: (s, p) => s.endsWith(p),
    index: (s, sub) => byteIndex(s, s.indexOf(sub)),
    indexAny: (s, chars) => indexAny(s, chars, false),
    indexFunc: (s, f) => indexFunc(s, f, false),
    indexRune: (s, c) => byteIndex(s, s.indexOf(String.fromCodePoint(c))),
    join: (elems, sep) => elems.join(sep),
    lastIndex: (s, sub) => byteIndex(s, s.lastIndexOf(sub)),
    lastIndexAny: (s, chars) => indexAny(s, chars, true),
    lastIndexFunc: (s, f) => indexFunc(s, f, true),
    map: (f, s) => Array.from(s, (c) => String.fromCodePoint(f(c.codePointAt(0)))).join(""),
    len: (s) => utf8Len(s),
    repeat(s, n) {
      if (n < 0) throw new Error("strings: negative Repeat count");
      return s.repeat(n);
    },
    replace,
    replaceAll: (s, old, nw) => replace(s, old, nw, -1),
    runeCount: (s) => codePoints(s).length,
    slice,
    split: (s, sep) => genSplit(s, sep, false, -1),
    splitAfter: (s, sep) => genSplit(s, sep, true, -1),
    splitAfterN: (s, sep, n) => genSplit(s, sep, true, n),
    splitN: (s, sep, n) => genSplit(s, sep, false, n),
    toLower: (s) => mapCase(s, lower),
    toTitle: (s) => mapCase(s, title),
    toUpper: (s) => mapCase(s, upper),
    // RuneScript strings are always valid UTF-8, so there is nothing to
    // replace.
    toValidUTF8: (s, _replacement) => s,
    trim: (s, chars) => (s === "" || chars === "" ? s : trimRight(trimLeft(s, cutset(chars)), cutset(chars))),
    trimLeft: (s, chars) => (s === "" || chars === "" ? s : trimLeft(s, cutset(chars))),
    trimPrefix: (s, p) => (s.startsWith(p) ? s.slice(p.length) : s),
    trimRight: (s, chars) => (s === "" || chars === "" ? s : trimRight(s, cutset(chars))),
    trimSpace: (s) => trimRight(trimLeft(s, spaces), spaces),
    trimFunc: (s, f) => trimRight(trimLeft(s, f), f),
    trimLeftFunc: (s, f) => trimLeft(s, f),
    trimRightFunc: (s, f) => trimRight(s, f),
    trimSuffix: (s, p) => (p !== "" && s.endsWith(p) ? s.slice(0, s.length - p.length) : s),
  };
  std.string = string;

  //@end

  //@section math
  // ---- std:math (OQ-MATH-01) ----
  //
  // Each function computes exactly what Go's math package computes, so
  // results are bit-identical with the interpreter. Host functions are
  // used only where IEEE 754 defines the result exactly (sqrt, floor, ...);
  // the others follow Go's code. A NaN's sign is never observable.

  const F64 = new Float64Array(1), U32 = new Uint32Array(F64.buffer);
  const LO = new Uint8Array(new Uint16Array([1]).buffer)[0] === 1 ? 0 : 1, HI = 1 - LO;

  function signbit(x) {
    if (x !== x) return false;
    F64[0] = x;
    return U32[HI] >>> 31 === 1;
  }

  // nextafter follows Go's Nextafter: the next float64 after x toward y.
  function nextafter(x, y) {
    if (x !== x || y !== y) return NaN;
    if (x === y) return x;
    if (x === 0) {
      U32[LO] = 1;
      U32[HI] = 0;
      return y < 0 ? -F64[0] : F64[0];
    }
    F64[0] = x;
    if ((y > x) === (x > 0)) { // away from zero: the bits grow
      U32[LO] = (U32[LO] + 1) >>> 0;
      if (U32[LO] === 0) U32[HI] = (U32[HI] + 1) >>> 0;
    } else {
      if (U32[LO] === 0) U32[HI] = (U32[HI] - 1) >>> 0;
      U32[LO] = (U32[LO] - 1) >>> 0;
    }
    return F64[0];
  }

  // remainder follows Go's Remainder (IEEE 754 remainder).
  function remainder(x, y) {
    const Tiny = 4.45014771701440276618e-308, HalfMax = Number.MAX_VALUE / 2;
    if (x !== x || y !== y || x === Infinity || x === -Infinity || y === 0) return NaN;
    if (y === Infinity || y === -Infinity) return x;
    let sign = false;
    if (x < 0) {
      x = -x;
      sign = true;
    }
    if (y < 0) y = -y;
    if (x === y) return sign ? -0 : 0;
    if (y <= HalfMax) x = x % (y + y); // Go's Mod, which is exact like %
    if (y < Tiny) {
      if (x + x > y) {
        x -= y;
        if (x + x >= y) x -= y;
      }
    } else {
      const yHalf = 0.5 * y;
      if (x > yHalf) {
        x -= y;
        if (x >= yHalf) x -= y;
      }
    }
    return sign ? -x : x;
  }

  // ---- transcendental functions: a port of internal/fmath ----
  //
  // internal/fmath is Go's own pure-Go code for these functions (see its
  // LICENSE-GO); this is a line-by-line port, so both targets compute the
  // same bits. JavaScript never fuses multiply-adds, matching fmath's
  // guarded products. Constants that Go folds exactly (4/Pi, 1/Ln10, ...)
  // are written as Go's float64 values, not recomputed here.

  const M64 = 0xFFFFFFFFFFFFFFFFn;
  function bitsOf(x) {
    F64[0] = x;
    return (BigInt(U32[HI]) << 32n) | BigInt(U32[LO]);
  }
  function fromBits(b) {
    b = BigInt.asUintN(64, b);
    U32[HI] = Number(b >> 32n);
    U32[LO] = Number(b & 0xFFFFFFFFn);
    return F64[0];
  }
  const PI = 3.141592653589793, PI2 = 1.5707963267948966, PI4 = 0.7853981633974483;
  const FOUR_OVER_PI = 1.2732395447351628, THREE_PI4 = 2.356194490192345;
  const LN2 = 0.6931471805599453, INV_LN2 = 1.4426950408889634, INV_LN10 = 0.4342944819032518;
